@page "/board"
@using sv_14588cd6e13647deb934212cfa1fb16c.Services
@inject ITaskService TaskService
@rendermode InteractiveServer

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (_loading)
{
    <p><em>Loading tasks...</em></p>
}
else if (_error is not null)
{
    <div class="alert alert-danger">@_error</div>
}
else
{
    <!-- Stats Bar -->
    <div class="stats-bar">
        <span class="stat-item"><strong>Total:</strong> @_allTasks.Count</span>
        <span class="stat-item"><strong>To Do:</strong> @GetColumnTasks("To Do").Count</span>
        <span class="stat-item"><strong>In Progress:</strong> @GetColumnTasks("In Progress").Count</span>
        <span class="stat-item"><strong>Done:</strong> @GetColumnTasks("Done").Count</span>
        <span class="stat-item stat-overdue"><strong>Overdue:</strong> @_allTasks.Count(t => t.DueDate < DateTime.Today)</span>
    </div>

    <!-- Search Bar -->
    <div class="search-bar">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="_searchQuery" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="board-container">
        @foreach (var column in _columns)
        {
            var tasks = GetFilteredColumnTasks(column);
            var columnIndex = Array.IndexOf(_columns, column);

            <div class="board-column">
                <div class="column-header">
                    <h3>@column</h3>
                    <span class="badge bg-secondary">@tasks.Count</span>
                </div>

                <div class="column-body">
                    @foreach (var task in tasks)
                    {
                        <div class="task-card">
                            <div class="task-title">@task.Title</div>
                            <div class="task-assignee">@task.Assignee</div>
                            <span class="priority-badge priority-@task.Priority.ToLower()">@task.Priority</span>
                            <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
                            <div class="task-actions">
                                @if (columnIndex > 0)
                                {
                                    <button class="btn btn-sm btn-outline-secondary"
                                            @onclick="() => MoveTask(task.Id, _columns[columnIndex - 1])">
                                        &larr; Move Left
                                    </button>
                                }
                                @if (columnIndex < _columns.Length - 1)
                                {
                                    <button class="btn btn-sm btn-outline-secondary"
                                            @onclick="() => MoveTask(task.Id, _columns[columnIndex + 1])">
                                        Move Right &rarr;
                                    </button>
                                }
                            </div>
                        </div>
                    }
                </div>

                @if (_showForm.ContainsKey(column) && _showForm[column])
                {
                    <div class="add-task-form">
                        <input type="text" class="form-control mb-1" placeholder="Title"
                               @bind="_formData[column].Title" />
                        <input type="text" class="form-control mb-1" placeholder="Assignee"
                               @bind="_formData[column].Assignee" />
                        <select class="form-select mb-1" @bind="_formData[column].Priority">
                            <option value="High">High</option>
                            <option value="Medium">Medium</option>
                            <option value="Low">Low</option>
                        </select>
                        <input type="date" class="form-control mb-1"
                               @bind="_formData[column].DueDate" />
                        <div class="form-buttons">
                            <button class="btn btn-sm btn-primary" @onclick="() => SaveTask(column)">Save</button>
                            <button class="btn btn-sm btn-secondary" @onclick="() => CancelForm(column)">Cancel</button>
                        </div>
                    </div>
                }
                else
                {
                    <button class="btn btn-sm btn-outline-primary add-task-btn"
                            @onclick="() => ShowAddForm(column)">
                        + Add Task
                    </button>
                }
            </div>
        }
    </div>
}

@code {
    private readonly string[] _columns = { "To Do", "In Progress", "Done" };
    private List<TaskItem> _allTasks = new();
    private bool _loading = true;
    private string? _error;
    private string _searchQuery = string.Empty;
    private Dictionary<string, bool> _showForm = new();
    private Dictionary<string, TaskFormModel> _formData = new();

    protected override async Task OnInitializedAsync()
    {
        foreach (var col in _columns)
        {
            _showForm[col] = false;
            _formData[col] = new TaskFormModel();
        }

        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }
    }

    private List<TaskItem> GetColumnTasks(string status)
        => _allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredColumnTasks(string status)
    {
        var tasks = GetColumnTasks(status);
        if (!string.IsNullOrWhiteSpace(_searchQuery))
        {
            tasks = tasks.Where(t => t.Title.Contains(_searchQuery, StringComparison.OrdinalIgnoreCase)).ToList();
        }
        return tasks;
    }

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = _allTasks.First(t => t.Id == taskId);
            var index = _allTasks.IndexOf(task);
            _allTasks[index] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            _error = $"Failed to move task: {ex.Message}";
        }
    }

    private void ShowAddForm(string column)
    {
        _showForm[column] = true;
        _formData[column] = new TaskFormModel { Priority = "Medium", DueDate = DateTime.Today };
    }

    private void CancelForm(string column)
    {
        _showForm[column] = false;
    }

    private async Task SaveTask(string column)
    {
        var form = _formData[column];
        if (string.IsNullOrWhiteSpace(form.Title))
            return;

        try
        {
            var newTask = await TaskService.CreateTaskAsync(form.Title, form.Assignee, form.Priority, form.DueDate);
            _allTasks.Add(newTask);
            _showForm[column] = false;
        }
        catch (Exception ex)
        {
            _error = $"Failed to create task: {ex.Message}";
        }
    }

    private class TaskFormModel
    {
        public string Title { get; set; } = string.Empty;
        public string Assignee { get; set; } = string.Empty;
        public string Priority { get; set; } = "Medium";
        public DateTime DueDate { get; set; } = DateTime.Today;
    }
}

